INSERT INTO kinds(id,silent,quiet_policy,eligibility_required) VALUES('LEAGUE_WEEKLY_RESULT',false,'DROP',false);
INSERT INTO templates(id,kind,locale,title,body) VALUES('LEAGUE_WEEKLY_RESULT.ko','LEAGUE_WEEKLY_RESULT','ko','{result, select, PROMOTED {🎉 우리 승격했어 !} RELEGATED {저번 주 리그가 종료되었어요!} other {새 리그 시작!}}','{result, select, PROMOTED {이번 주 몰입으로 {previousTierLevel, select, 1 {뽀시래기} 2 {예열 모드} 3 {초집중 모드} 4 {갓생러} 5 {집중 정복자} other {뽀시래기}} 리그에서 {newTierLevel, select, 1 {뽀시래기} 2 {예열 모드} 3 {초집중 모드} 4 {갓생러} 5 {집중 정복자} other {뽀시래기}} 리그에 올라갔어. 새 순위 보러 올래?} RELEGATED {저번 주 {previousTierLevel, select, 1 {뽀시래기} 2 {예열 모드} 3 {초집중 모드} 4 {갓생러} 5 {집중 정복자} other {뽀시래기}} 리그에서 이번 주 {newTierLevel, select, 1 {뽀시래기} 2 {예열 모드} 3 {초집중 모드} 4 {갓생러} 5 {집중 정복자} other {뽀시래기}} 리그로 이동했어요. 조금 더 힘내봐요!} other {이번 주 리그가 새로 시작됐어. 오늘 목표는? 지금 바로 몰입 시작하자!}}');
INSERT INTO templates(id,kind,locale,title,body) VALUES('LEAGUE_WEEKLY_RESULT.en','LEAGUE_WEEKLY_RESULT','en','{result, select, PROMOTED {🎉 We moved up!} RELEGATED {Last week’s league is over!} other {A new league begins!}}','{result, select, PROMOTED {Your focus took you from {previousTierLevel, select, 1 {Rookie} 2 {Warm-up} 3 {Deep Focus} 4 {Life Master} 5 {Focus Champion} other {Rookie}} to {newTierLevel, select, 1 {Rookie} 2 {Warm-up} 3 {Deep Focus} 4 {Life Master} 5 {Focus Champion} other {Rookie}}. Check your new rank!} RELEGATED {You moved from {previousTierLevel, select, 1 {Rookie} 2 {Warm-up} 3 {Deep Focus} 4 {Life Master} 5 {Focus Champion} other {Rookie}} to {newTierLevel, select, 1 {Rookie} 2 {Warm-up} 3 {Deep Focus} 4 {Life Master} 5 {Focus Champion} other {Rookie}}. Let’s keep going!} other {A new week, a new league. Start focusing on your goal!}}');
INSERT INTO templates(id,kind,locale,title,body) VALUES('LEAGUE_WEEKLY_RESULT.ja','LEAGUE_WEEKLY_RESULT','ja','{result, select, PROMOTED {🎉 昇格したよ！} RELEGATED {先週のリーグが終了しました！} other {新しいリーグがスタート！}}','{result, select, PROMOTED {今週の集中で{previousTierLevel, select, 1 {ひよっこ} 2 {ウォームアップ} 3 {超集中} 4 {充実ライフ} 5 {集中の達人} other {ひよっこ}}から{newTierLevel, select, 1 {ひよっこ} 2 {ウォームアップ} 3 {超集中} 4 {充実ライフ} 5 {集中の達人} other {ひよっこ}}へ昇格したよ。新しい順位を見てみよう！} RELEGATED {{previousTierLevel, select, 1 {ひよっこ} 2 {ウォームアップ} 3 {超集中} 4 {充実ライフ} 5 {集中の達人} other {ひよっこ}}から{newTierLevel, select, 1 {ひよっこ} 2 {ウォームアップ} 3 {超集中} 4 {充実ライフ} 5 {集中の達人} other {ひよっこ}}へ移動しました。今週も頑張ろう！} other {今週の目標は？さっそく集中を始めよう！}}');
INSERT INTO templates(id,kind,locale,title,body) VALUES('LEAGUE_WEEKLY_RESULT.zh-Hant','LEAGUE_WEEKLY_RESULT','zh-Hant','{result, select, PROMOTED {🎉 我們晉級了！} RELEGATED {上週的聯賽結束了！} other {新聯賽開始了！}}','{result, select, PROMOTED {這週的專注讓你從{previousTierLevel, select, 1 {新手} 2 {暖身模式} 3 {超專注} 4 {自律達人} 5 {專注王者} other {新手}}晉級到{newTierLevel, select, 1 {新手} 2 {暖身模式} 3 {超專注} 4 {自律達人} 5 {專注王者} other {新手}}。來看看新排名！} RELEGATED {從{previousTierLevel, select, 1 {新手} 2 {暖身模式} 3 {超專注} 4 {自律達人} 5 {專注王者} other {新手}}移動到{newTierLevel, select, 1 {新手} 2 {暖身模式} 3 {超專注} 4 {自律達人} 5 {專注王者} other {新手}}。這週繼續加油！} other {這週的目標是什麼？現在就開始專注吧！}}');
INSERT INTO deeplinks(id,url_template,data_template) VALUES('LEAGUE_WEEKLY_RESULT','{result, select, PROMOTED {gromo://league} RELEGATED {gromo://focus} other {gromo://league}}','{}'::jsonb);
