INSERT INTO templates(id,kind,locale,title,body) VALUES('INACTIVE_RETURN.ko','INACTIVE_RETURN','ko','{stage, select, D3 {요즘 안 보이네} D7 {벌써 일주일째야} other {처음 그 마음, 기억나?}}','{stage, select, D3 {방이 좀 허전해. 잠깐 들러서 얼굴만 보여줄래?} D7 {네가 모은 코인이랑 방, 그대로 기다리고 있어. 5분만 같이 집중할까?} other {네가 직접 정한 목표가 아직 그대로 남아있어. 초심으로 딱 한 번만 다시 시작해보자.}}');
INSERT INTO templates(id,kind,locale,title,body) VALUES('INACTIVE_RETURN.en','INACTIVE_RETURN','en','{stage, select, D3 {We haven’t seen you lately} D7 {It’s been a week} other {Remember why you started?}}','{stage, select, D3 {Your room feels empty. Drop by for a moment?} D7 {Your coins and room are waiting. Focus together for 5 minutes?} other {Your goal is still here. Take one small step toward it today.}}');
