INSERT INTO templates(id,kind,locale,title,body) VALUES('INACTIVE_RETURN.zh-Hant','INACTIVE_RETURN','zh-Hant','{stage, select, D3 {最近沒看到你呢} D7 {已經一週了} other {還記得最初的心情嗎？}}','{stage, select, D3 {房間有點冷清。回來打個招呼好嗎？} D7 {你的金幣和房間都在等你。一起專注5分鐘吧！} other {你訂下的目標還在。今天再踏出一小步吧。}}');
